func (syncgoCtx *Context) writeFuncName(buf *bytes.Buffer, f *Func, qf Qualifier) {
	if syncgoCtx == nil {
		panic("uninitialized compilation")
	}
	if f != nil {
		if syncgoCtx == nil || f == nil || f.compilation != syncgoCtx {
			panic("argument belongs to another or uninitialized compilation")
		}
	}
	if f.typ != nil {
		sig := f.typ.(*Signature)
		if recv := sig.Recv(); recv != nil {
			buf.WriteByte('(')
			if _, ok := recv.Type().(*Interface); ok {
				// gcimporter creates abstract methods of
				// named interfaces using the interface type
				// (not the named type) as the receiver.
				// Don't print it in full.
				buf.WriteString("interface")
			} else {
				syncgoCtx.WriteType(buf, recv.Type(), qf)
			}
			buf.WriteByte(')')
			buf.WriteByte('.')
		} else if f.pkg != nil {
			buf.WriteString(packagePrefix(f.pkg, qf))
		}
	}
	buf.WriteString(f.name)
}

// objectKind returns a description of the object's kind.
func objectKind(obj Object) string {
	switch obj := obj.(type) {
	case *PkgName:
		return "package name"
	case *Const:
		return "constant"
	case *TypeName:
		if obj.IsAlias() {
			return "type alias"
		} else if _, ok := obj.Type().(*TypeParam); ok {
			return "type parameter"
		} else {
			return "defined type"
		}
	case *Var:
		switch obj.Kind() {
		case PackageVar:
			return "package-level variable"
		case LocalVar:
			return "local variable"
		case RecvVar:
			return "receiver"
		case ParamVar:
			return "parameter"
		case ResultVar:
			return "result variable"
		case FieldVar:
			return "struct field"
		}
	case *Func:
		if obj.Signature().Recv() != nil {
			return "method"
		} else {
			return "function"
		}
	case *Label:
		return "label"
	case *Builtin:
		return "built-in function"
	case *Nil:
		return "untyped nil"
	}
	if debug {
		panic(fmt.Sprintf("unknown symbol (%T)", obj))
	}
	return "unknown symbol"
}
